// ============================================================
// API Configuration — Gemini Only (Free Forever)
// Only 1 key needed in .env:
//   REACT_APP_GEMINI_API_KEY → aistudio.google.com/app/apikey
//
// Uses gemini-2.0-flash-lite (higher free tier limits)
// Auto-retries on rate limit with countdown
// ============================================================

const GEMINI_MODEL = "gemini-2.0-flash-lite";

function delay(ms) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

async function geminiRequest(prompt, maxTokens = 900, retries = 3) {
  const apiKey = process.env.REACT_APP_GEMINI_API_KEY;
  if (!apiKey) throw new Error("Missing REACT_APP_GEMINI_API_KEY in .env — get it free at aistudio.google.com/app/apikey");

  for (let attempt = 1; attempt <= retries; attempt++) {
    const res = await fetch(
      `https://generativelanguage.googleapis.com/v1beta/models/${GEMINI_MODEL}:generateContent?key=${apiKey}`,
      {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          contents: [{ parts: [{ text: prompt }] }],
          generationConfig: { maxOutputTokens: maxTokens },
        }),
      }
    );

    // Rate limited — wait and retry automatically
    if (res.status === 429) {
      if (attempt < retries) {
        const waitSec = attempt * 20; // 20s, 40s, 60s
        console.log(`Rate limited. Waiting ${waitSec}s before retry ${attempt}/${retries}...`);
        await delay(waitSec * 1000);
        continue;
      } else {
        throw new Error("Rate limit reached after 3 attempts. Please wait 2 minutes and try again.");
      }
    }

    if (!res.ok) {
      const err = await res.json().catch(() => ({}));
      throw new Error(`Gemini API error: ${err?.error?.message || res.status}`);
    }

    const data = await res.json();
    return data.candidates?.[0]?.content?.parts?.[0]?.text || "";
  }
}

// ---------- CHATGPT — simulated via Gemini ----------
export async function callChatGPT(user) {
  await delay(2000);
  return await geminiRequest(
    `You are ChatGPT made by OpenAI. Respond exactly like ChatGPT:
- Confident, helpful, direct tone
- Numbered list format
- Name exactly 4-6 specific real product brands
- One short reason per product
- No AI disclaimers

Question: ${user}`
  );
}

// ---------- CLAUDE — simulated via Gemini ----------
export async function callClaude(system, user, maxTokens = 900) {
  await delay(2000);

  // Analysis call — pass through as JSON instruction
  if (system.toLowerCase().includes("json")) {
    return await geminiRequest(`${system}\n\n${user}`, maxTokens);
  }

  // Claude persona simulation
  return await geminiRequest(
    `You are Claude made by Anthropic. Respond like Claude:
- Thoughtful, balanced, nuanced tone
- Name 4-6 specific real product brands
- Note why each suits different needs
- Acknowledge individual variation

Question: ${user}`,
    maxTokens
  );
}

// ---------- GEMINI — real response ----------
export async function callGemini(user) {
  await delay(2000);
  return await geminiRequest(
    `You are Gemini made by Google. Respond like Gemini:
- Data-driven, informative tone
- Clean list format
- Name 4-6 specific real top-rated product brands
- Reference popularity or ratings where relevant

Question: ${user}`
  );
}
